import figma from "figma";

const instance = figma.selectedInstance;

const attr = (name, value) => {
  if (value === undefined || value === false) return "";
  if (value === true) return ` ${name}`;
  if (typeof value === "number") return ` ${name}={${value}}`;
  return value.startsWith("{") ? ` ${name}=${value}` : ` ${name}="${value}"`;
};
const codeOf = (node) =>
  node && node.type === "INSTANCE" ? node.executeTemplate().example : undefined;

const size = instance.getEnum("Size", { sm: "sm", md: "md", lg: "lg" });
const spacing = instance.getEnum("Spacing", {
  compact: "compact",
  loose: "loose",
});
const avatar1 = codeOf(
  instance.findLayers((node) => node.name === "Avatar")[0],
);
const avatar2 = codeOf(
  instance.findLayers((node) => node.name === "Avatar")[1],
);
const avatar3 = codeOf(
  instance.findLayers((node) => node.name === "Avatar")[2],
);

export default {
  id: "Avatar group",
  example: figma.code`<HvAvatarGroup${attr("size", size)}${attr("spacing", spacing)}>
  ${avatar1 ?? ""}
  ${avatar2 ?? ""}
  ${avatar3 ?? ""}
</HvAvatarGroup>`,
  imports: ['import { HvAvatarGroup } from "@pentaho/uikit-react-core";'],
  metadata: { nestable: true },
};
